-                          .build());
-        }
-        if (!Strings.isNullOrEmpty(jmxDomain)) {
-            LOG.info("Configuring stats with jmx");
-            jmx = JmxReporter.forRegistry(getMetrics())
-                .inDomain(jmxDomain)
