-                .convertDurationsTo(TimeUnit.MILLISECONDS)
-                .build();
-            jmx.start();
-        }
-
-        for (ScheduledReporter r : reporters) {
-            r.start(metricsOutputFrequency, TimeUnit.SECONDS);
-        }
-    }
-
-    @Override
