+    public void testGetListOfEntriesOfLedgerWithEntriesNotStripedToABookie() throws Exception {
+        ClientConfiguration conf = new ClientConfiguration();
+        conf.setMetadataServiceUri(zkUtil.getMetadataServiceUri());
