+
+    File(int id) {
+        this.id = id;
+
+        long now = System.currentTimeMillis(); // TODO(cgdecker): Use a Clock
+        this.creationTime = now;
+        this.lastAccessTime = now;
+        this.lastModifiedTime = now;
+    }
+
+    /** Returns the ID of this file. */
