+    void opened() {
+    }
+
+    /**
+     * Called when a stream or channel to this file is closed. If there are no more
+     * streams or channels open to the file and it has been deleted, its contents
+     * may be deleted.
+     */
+    void closed() {
+    }
+
+    /**
+     * Called when (a single link to) this file is deleted. There may be links
+     * remaining. Does nothing by default.
+     */
+    void deleted() {
+    }
+
+    /** Returns whether or not this file is a root directory of the file system. */
+    final boolean isRootDirectory() {
+        // only root directories have their parent link pointing to themselves
+        return isDirectory() && equals(((Directory) this).parent());
