+    void unlinked() {
+    }
+
+    /** Increments the link count for this file. */
+    final synchronized void incrementLinkCount() {
+        links++;
+    }
+
+    /** Decrements the link count for this file. */
+    final synchronized void decrementLinkCount() {
+        links--;
