+            String result = session.getCurrentProject().getDependencyArtifacts().stream()
+                    .filter(a -> !validate(a))
+                    .collect(
+                            StringBuilder::new,
+                            (messageBuilder, node) -> messageBuilder
+                                    .append(node.getId())
+                                    .append(" <--- ")
+                                    .append(getErrorMessage()),
+                            (m1, m2) -> m1.append(m2.toString()))
+                    .toString();
